//! SeaORM entity for guest/parent chat messages.
//!
//! `user_id` holds the anonymous UUID generated by the browser and stored in
//! `localStorage`. It is deliberately kept as TEXT (not a foreign key) so that
//! a real account can later be linked to the same conversation history by
//! adding an accounts table that maps `account_id -> guest_uuid`.

use sea_orm::entity::prelude::*;

#[derive(Clone, Debug, PartialEq, DeriveEntityModel, Eq)]
#[sea_orm(table_name = "chat_messages")]
pub struct Model {
    #[sea_orm(primary_key)]
    pub id: i32,
    /// Guest UUID (v4) generated client-side. Indexed for history queries.
    #[sea_orm(column_type = "Text")]
    pub user_id: String,
    /// `user` or `assistant`.
    #[sea_orm(column_type = "Text")]
    pub role: String,
    #[sea_orm(column_type = "Text")]
    pub content: String,
    /// UTC timestamp. Ordered together with `id` to make history replay stable.
    pub created_at: DateTimeUtc,
}

#[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
pub enum Relation {}

impl ActiveModelBehavior for ActiveModel {}
